// Blog only (/pages/blog/ and /pages/blog/<slug>/). Posts migrated from Squarespace: public/db/blog.json.
// Post pages are generated by tools/generar-paginas-producto.py and call renderPost(); the slug comes from the URL.

const longDateES = (iso) => iso ? new Date(`${iso}T12:00:00`).toLocaleDateString('es-MX', { day: 'numeric', month: 'long', year: 'numeric' }) : '';

const PostCard = ({ post }) => (
    <a href={`/pages/blog/${post.slug}/`} className="group reveal flex flex-col">
        <div className="rounded-3xl overflow-hidden bg-blush-50 aspect-[4/3]">
            {post.cover && <Img src={post.cover} alt="" className="w-full h-full object-cover group-hover:scale-[1.03] transition-transform duration-700" />}
        </div>
        <p className="label text-ink-400 mt-5">{longDateES(post.date)}{post.author ? ` · ${post.author}` : ''}</p>
        <h2 className="text-3xl mt-2 first-letter:uppercase group-hover:text-blush-500">{post.title}</h2>
        <p className="text-sm text-ink-500 mt-2 line-clamp-3">{post.excerpt}</p>
    </a>
);

const BlogIndex = () => {
    const { status, data } = useJson('blog');
    return (
        <>
            <PageHero eyebrow="Blog de skincare & tratamientos" title="Piel" script="informada" />
            <section className="max-w-7xl mx-auto px-4 md:px-8 pb-16">
                {status === 'loading' && <div className="h-64 rounded-3xl bg-blush-50 animate-pulse" />}
                {status === 'error' && <p className="text-center text-ink-400">No pudimos cargar los artículos.</p>}
                {status === 'ready' && (
                    <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-x-8 gap-y-16">
                        {data.posts.map(p => <PostCard key={p.slug} post={p} />)}
                    </div>
                )}
            </section>
        </>
    );
};

const BlogPost = () => {
    const { status, data } = useJson('blog');
    const slug = window.location.pathname.split('/').filter(Boolean).pop();
    if (status === 'loading') return <div className="max-w-3xl mx-auto px-4 py-24"><div className="h-96 rounded-3xl bg-blush-50 animate-pulse" /></div>;
    const i = status === 'ready' ? data.posts.findIndex(p => p.slug === slug) : -1;
    if (i < 0) return (
        <PageHero eyebrow="Blog" title="Artículo" script="no encontrado">
            <a href="/pages/blog/" className="btn btn-dark mt-10">Ver el blog</a>
        </PageHero>
    );
    const post = data.posts[i];
    const more = data.posts.filter(p => p.slug !== slug).slice(0, 3);
    return (
        <>
            <article className="max-w-3xl mx-auto px-4 md:px-8 pt-14 pb-10">
                <nav className="label text-ink-400 mb-8" aria-label="Ruta"><a href="/pages/blog/" className="hover:text-ink">Blog</a></nav>
                <p className="label text-ink-400">{longDateES(post.date)}{post.author ? ` · ${post.author}` : ''}</p>
                <h1 className="text-5xl md:text-6xl mt-3 first-letter:uppercase">{post.title}</h1>
                <Blocks blocks={post.blocks} className="mt-10 text-lg" />
            </article>
            <WhatsAppCTA />
            {more.length > 0 && (
                <section className="max-w-7xl mx-auto px-4 md:px-8 py-16">
                    <SectionTitle kicker="Sigue leyendo" script="artículos">Más</SectionTitle>
                    <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-8">{more.map(p => <PostCard key={p.slug} post={p} />)}</div>
                </section>
            )}
        </>
    );
};

const renderPost = () => renderPage(BlogPost);
